#!/usr/bin/env python3
import json
import re
from datetime import datetime, timezone

def is_private_ipv4(ip):
    """Check if IP is a private IPv4 address."""
    # Must be IPv4 format (4 dot-separated numbers)
    parts = ip.split('.')
    if len(parts) != 4:
        return False
    try:
        octets = [int(p) for p in parts]
    except ValueError:
        return False

    # 10.0.0.0/8
    if octets[0] == 10:
        return True
    # 172.16.0.0/12 (172.16.x.x - 172.31.x.x)
    if octets[0] == 172 and 16 <= octets[1] <= 31:
        return True
    # 192.168.0.0/16
    if octets[0] == 192 and octets[1] == 168:
        return True
    return False

def map_action(action):
    """Map raw action to normalized action."""
    mapping = {
        'Successful': 'allow',
        'Dropped': 'drop',
        'Rejected': 'deny',
        'Reset': 'reset'
    }
    return mapping.get(action, None)

def epoch_to_iso(epoch):
    """Convert Unix epoch to ISO8601 UTC string with Z suffix."""
    dt = datetime.fromtimestamp(int(epoch), tz=timezone.utc)
    return dt.strftime('%Y-%m-%dT%H:%M:%SZ')

def parse_line(line):
    """Parse a tab-separated log line."""
    parts = line.strip().split('\t')
    if len(parts) < 7:
        return None

    timestamp_str = parts[0]
    src_ip = parts[1]
    # parts[2] is src_port (not needed for output)
    dst_ip = parts[3]
    dst_port_str = parts[4]  # can be empty
    protocol = parts[5]
    action = parts[6]

    return {
        'timestamp_str': timestamp_str,
        'src_ip': src_ip,
        'dst_ip': dst_ip,
        'dst_port_str': dst_port_str,
        'protocol': protocol,
        'action': action
    }

def main():
    records = []
    seen = set()  # for deduplication: (src_ip, dst_ip, protocol, port)

    with open('/workdir/input.txt', 'r') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue

            parsed = parse_line(line)
            if parsed is None:
                continue

            # Filter: must be TCP or UDP (not ICMP)
            if parsed['protocol'] not in ('tcp', 'udp'):
                continue

            # Filter: dst_ip must be private IPv4
            if not is_private_ipv4(parsed['dst_ip']):
                continue

            # Also ensure src_ip is valid IPv4 (filter out IPv6)
            # IPv6 addresses have colons, so we can check that
            if ':' in parsed['src_ip']:
                continue
            if ':' in parsed['dst_ip']:
                continue

            # Parse timestamp
            try:
                timestamp = epoch_to_iso(parsed['timestamp_str'])
            except:
                continue

            # Map action
            action = map_action(parsed['action'])
            if action is None:
                continue

            # Parse port (can be empty/null)
            port = None
            if parsed['dst_port_str'].strip():
                try:
                    port = int(parsed['dst_port_str'])
                except ValueError:
                    port = None

            # Create dedup key
            dedup_key = (parsed['src_ip'], parsed['dst_ip'], parsed['protocol'], port)
            if dedup_key in seen:
                continue
            seen.add(dedup_key)

            records.append({
                'timestamp': timestamp,
                'src_ip': parsed['src_ip'],
                'dst_ip': parsed['dst_ip'],
                'protocol': parsed['protocol'],
                'action': action,
                'port': port
            })

    # Sort by timestamp, then by src_ip, dst_ip, protocol, port for consistency
    records.sort(key=lambda r: (r['timestamp'], r['src_ip'], r['dst_ip'], r['protocol'], r['port']))

    # Write output
    with open('/workdir/normalized.json', 'w') as f:
        json.dump(records, f, indent=2)

    print(f"Processed {len(records)} records")

if __name__ == '__main__':
    main()
